/* "What kind of battalion would you like sent?" -- cancel a filed battalion
 * request, or choose one of the side's available element types and the own
 * city that receives it, then file the request. */
void opeu_request_arms(uint8_t ds[65536], HostEvent event, uint16_t scratch) {
  CITY_PTR dest;
  LOCAL_XY
  BUFFER(buffer, 50, 4);
  RequestSlotView order;
  if (PENDING(1)) {
    if (!CANCEL(ARMS_TEXT))
      return;
    FILED_KIND(1) = 0xff;
  }
  PANEL();
  for (count = i = 0; i < 8; i++)
    count += TYPES(SIDE_FLAGS(SIDE), i, TYPE_SLOT(count));
  DIALOG_COUNT = count + 1;
  MESSAGE(WHICH_TEXT, RECORD2);
  if (!LIST_DIALOG(1, 7))
    return;
  X = VIEW_X;
  Y = VIEW_Y;
  MESSAGE(WHERE_TEXT, RECORD2);
  for (;;) {
    if (!PICK())
      return;
    dest = FIND(X, Y);
    if (dest && CITY_SIDE(dest) == SIDE)
      break;
  }
  FORMAT(buffer, CONFIRM_TEXT, dest);
  if (!CONFIRM(buffer, RECORD2))
    return;
  order.target   = TARGET_OF(dest);
  order.argument = TYPE_LIST(ROW);
  order.kind     = 1;
  FILE_REQUEST(order);
  DELAY(SIDE) = 1;
}

